import React, { useState, useEffect } from 'react';
import api from '../api';

const Dashboard = () => {
  const [user, setUser] = useState(null);
  const [mhs, setMhs] = useState(null);

  // Ambil data user berdasarkan token yang ada di localStorage
  useEffect(() => {
    const fetchUser = async () => {
      try {
        const response = await api.get(`/me`, {
          headers: { Authorization: `Bearer ${localStorage.getItem("token")}` },
        });
        setUser(response.data.user);
      } catch (error) {
        console.error("Failed to fetch user:", error);
      }
    };
    fetchUser();
  }, []);
  
  useEffect(() => {
    const fetchMhs = async () => {
      if (!user?.mahasiswa_id) return;
      try {
        const response = await api.get(`/mahasiswa/me/${user.mahasiswa_id}`, {
          headers: { Authorization: `Bearer ${localStorage.getItem("token")}` },
        });
        setMhs(response.data.mhs);
      } catch (error) {
        console.error("Failed to fetch mhs:", error);
      }
    };
    fetchMhs();
  }, [user]);

  return (
    <div className="flex flex-col h-screen font-sans bg-teal-100">
      {/* Header */}
      <header className="bg-teal-200 text-teal-800 px-6 py-4 flex justify-between items-center shadow">
        <h1 className="text-xl font-bold">Panel Mhs</h1>
        <div className="flex items-center">
          <img
            src={mhs ? mhs.gambar : 'not found'} // Ganti dengan URL gambar dari Laravel
            alt="Deskripsi Gambar"
            className="w-10 h-10 bg-teal-800 mr-4 rounded-full object-cover"
          />
          <span>{user ? user.name : 'Loading...'}</span> {/* Nama user */}
        </div>
      </header>

      {/* Container */}
      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar */}
        <aside className="w-48 bg-teal-700 text-white flex-shrink-0">
          <nav>
            <ul className="space-y-2 p-4">
              <li>
                <a
                  href="/dashboardMhs"
                  className="block px-4 py-2 rounded hover:bg-teal-600"
                >
                  Dashboard
                </a>
              </li>
              <li>
                <a
                  href="/jadwalMhs"
                  className="block px-4 py-2 rounded hover:bg-teal-600"
                >
                  Jadwal
                </a>
              </li>
              <li>
                <a
                  href="/pembayaranMhs"
                  className="block px-4 py-2 rounded hover:bg-teal-600"
                >
                  Pembayaran
                </a>
              </li>
              <li>
                <a
                  href="/absenMhs"
                  className="block px-4 py-2 rounded hover:bg-teal-600"
                >
                  Presensi
                </a>
              </li>
              <li>
                <a
                  href="/"
                  className="block px-4 py-2 rounded hover:bg-teal-600"
                >
                  Logout
                </a>
              </li>
            </ul>
          </nav>
        </aside>

        {/* Main Content */}
        <main className="flex-1 bg-teal-50 p-6 overflow-y-auto">
          <h2 className="text-2xl font-bold mb-4">Dashboard</h2>
          <p className="text-gray-700 mb-6">
            Selamat datang di panel user, silahkan lihat jadwal dan keperluan lain anda disini.
          </p>

          {/* Profil Card */}
          <div className="bg-teal-200 p-6 rounded-lg shadow flex flex-col items-center text-teal-800 mb-6">
            {mhs ? (
              <>
              <img
                src={mhs.gambar} // Ganti dengan URL gambar dari Laravel
                alt="Deskripsi Gambar"
                className="w-48 h-48 bg-teal-800 rounded-full mb-4 object-cover"
              />
                <h3 className="font-bold">NIM:</h3>
                <p className="mb-2">{mhs.nim}</p>
                <h3 className="font-bold">Nama:</h3>
                <p className="mb-2">{mhs.nama}</p>
                <h3 className="font-bold">Tempat, Tanggal Lahir:</h3>
                <p className="mb-2">{mhs.tempat}, {mhs.tgl_lahir}</p>
                <h3 className="font-bold">Alamat:</h3>
                <p className="mb-2">{mhs.alamat}</p>
                <h3 className="font-bold">No Tlp:</h3>
                <p className="mb-2">{mhs.no_tlp}</p>
                <h3 className="font-bold">Email:</h3>
                <p className="mb-2">{mhs.email}</p>
              </>
            ) : (
              <p>Loading...</p>
            )}
          </div>
        </main>
      </div>
    </div>
  );
};

export default Dashboard;
